class stringx
{
  char *chars;
  void *my_buf;
public:
  stringx(const stringx&);
  ~stringx();
};

class FEMenuEntry
{
public:
  void Disable(bool d = true);
  bool GetDisable();
  void SetText(stringx str);
};

class FEMenu
{
  char pad0[76];
protected:
  FEMenuEntry *highlighted;
  char pad1[40];
public:
  void Init();
  void setHigh(FEMenuEntry *, bool);
  void HighlightDefault();
  void SetHelpText(int);
};

class PauseMenuSystem
{
  char pad[160];
public:
  int pause_player;
  bool IsResumable(FEMenu *menu) const;
};

class game
{
  char pad[192];
  int player_devices[4];
public:
  int get_player_device(int player) { return player_devices[player]; }
};

class rumble_manager
{
public:
  bool isOn(int controller);
};

extern game *g_game_ptr;
extern rumble_manager rumbleMan;
extern stringx ksGlobalTextArray[];

class OptionsMenuClass : public FEMenu
{
  PauseMenuSystem *sys;
  FEMenuEntry *cameraEntry;
  FEMenuEntry *rumbleEntry;
  FEMenuEntry *displayEntry;
  bool rumble;
  float rumbleTimer;
public:
  void OnActivate() __asm__("OnActivate__16OptionsMenuClass");
};

enum
{
  NATIVE_RUMBLE_ON = 38,
  NATIVE_RUMBLE_OFF = 39,
  HF_UP = 0x001,
  HF_DOWN = 0x002,
  HF_SELECT = 0x010,
  HF_BACK = 0x020,
  HF_RESUME = 0x040
};

void OptionsMenuClass::OnActivate()
{
	FEMenuEntry *	oldHigh;
	rumbleTimer = -1;
	if (sys->pause_player != -1)
	{
		cameraEntry->Disable(false);

		rumble = rumbleMan.isOn( g_game_ptr->get_player_device( sys->pause_player ) );
		rumbleEntry->SetText( ksGlobalTextArray[ rumble ? NATIVE_RUMBLE_ON : NATIVE_RUMBLE_OFF ] );
		rumbleEntry->Disable(false);
	}
	else
	{
		cameraEntry->Disable(true);
		rumbleEntry->Disable(true);
	}

	// Reposition entries.
	oldHigh = highlighted;
	Init();
	if (oldHigh && !oldHigh->GetDisable())
		setHigh(oldHigh, false);
	else
		HighlightDefault();

	// Only let Start = Continue if we can continue playing. (dc 07/12/02)
	if (sys->IsResumable(this))
		SetHelpText(HF_RESUME | HF_UP | HF_DOWN | HF_SELECT | HF_BACK);
	else
		SetHelpText(HF_UP | HF_DOWN | HF_SELECT | HF_BACK);
}
